import java.io.File

const val MOD: Long = 998244353L

fun mod(num: Long): Long {
    if (num >= MOD) return num % MOD
    else if (num < 0) return (num % MOD + MOD) % MOD
    return num
}

fun mul(vararg args: Long): Long {
    if (args.isEmpty()) throw Exception("参数不能为空")
    if (args.size == 1) return args[0]
    val a = args[0]
    val b = args[1]
    if (args.size > 2) {
        val rest = LongArray(args.size - 1)
        rest[0] = mul(a, b)
        for (i in 2 until args.size) rest[i - 1] = args[i]
        return mul(*rest)
    }
    return ((a / 65536) * b % MOD * 65536 + (a and 65535L) * b) % MOD
}

fun getPrimes(n: Int): IntArray {
    val nums = IntArray(n + 1) { 1 }
    nums[0] = 0
    if (n >= 1) nums[1] = 0
    val primes = ArrayList<Int>()
    for (i in 2..n) {
        if (nums[i] != 0) primes.add(i)
        var j = 0
        while (j < primes.size && primes[j].toDouble() <= n.toDouble() / i) {
            nums[primes[j] * i] = 0
            if (i % primes[j] == 0) break
            j++
        }
    }
    return nums
}

fun solve(read: () -> String): Long {
    val parts = read().trim().split(Regex("\\s+"))
    val n = parts[0].toInt()
    val m = parts[1].toLong()
    var pre = 1L
    val M = mod(m)
    var res = 0L
    var ans = M
    var ans1 = M
    val p = getPrimes(n + 10)
    for (i in 2..n) {
        if (pre <= m && p[i] != 0) pre = pre * i
        if (pre > m) {
            ans = 0L
        } else {
            ans = mul(ans, m / pre)
        }
        ans1 = mul(ans1, M)
        res = mod(res + ans1 - ans)
    }
    return res
}

fun main(r: () -> String): String {
    try {
        val t = 1
        val res = arrayOfNulls<String>(t)
        val limit = 0
        for (i in 0 until t) {
            val s = solve(r).toString()
            if (t < limit) {
            } else {
                res[i] = s
            }
        }
        if (t >= limit) {
            return res.joinToString("\n")
        }
    } catch (error: Exception) {
        println(error)
    }
    return ""
}

fun main() {
    val inputs = System.`in`.bufferedReader().readText().split(Regex("\r?\n"))
    var i = 0
    val read = { inputs[i++] }
    val output = main(read)
    print(output)
}
